//! 🧪️ A native document Report captures its original result and closes every private preparation through the same caller.
use super::*;
pub(crate) fn prepare_report(store:&mut store::ConfigStore<State,Mutation>,caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner)->store::os_store::replay::EditReplayResult<State,Mutation>{
 let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();let id=String::from("original-publication-edit");let mutation_id=protocol::MutationId(String::from("original-publication-op"));let meta=protocol::MutationMeta{mutation_id:Some(mutation_id.clone()),dependencies:Vec::new(),base_version:0,author_id:None,timestamp:protocol::HybridLogicalTimestamp::new(1,0),undo_policy:protocol::UndoPolicy::ExactBaseOnly,payload_hash:None,semantic_kind:None,label:None,group_id:None,origin:protocol::MutationOrigin::Owner,transaction:None};let edit=protocol::Edit{id:id.clone(),actor:Some(store.local_actor_id().0.clone()),line:None,forwards:vec![Mutation::Zoom{zoom:law["authored"].as_f64().unwrap()}],inverse:vec![Mutation::Zoom{zoom:law["genesis"].as_f64().unwrap()}].into(),mutation_meta:vec![meta],verb:None,sequence_number:0,started_at:String::from("2026-10-21T00:00:00Z"),finished_at:None};
 {let parts=store.parts();let key=parts.log.envelope.vcs.edits.try_push(edit).ok().unwrap();let digest=store::os_store::ledger::CursorRevisionAccumulator::hash_record(b"edit-id",&[id.as_bytes()]);parts.log.applied_edit_ids.push(id.clone());parts.log.envelope.cursor.as_mut().unwrap().applied_edit_ids.push(id);parts.cursor.revision_accumulator.applied.push(store::os_store::ledger::CursorRevisionRecord::new(Some(key),digest,[0;32],[0;32]));parts.cursor.revision_accumulator.indexed_edits.insert(digest,(0,1));parts.cursor.revision_accumulator.mutation_positions.insert(mutation_id.clone(),(0,0,digest));}
 let payload=format!("op{{\"kind\":\"zoom\",\"zoom\":{}}}",law["replacement"].as_f64().unwrap()).into_bytes();let drafts=protocol::HistoryInputDrafts::from([(mutation_id,protocol::InputReplacement::Input{schema:String::from("test.window.genesis"),payload})]);let mut replay=Some(store.begin_derived_report_replay(drafts,None).unwrap());let g=RetainedCloneGrant{maximum_copy_bytes:32768,maximum_capacity_bytes:16<<20,..TURN};
 for index in 0..262144{let ready=turn(caller,decoder,g,|cx|{let grant=cx.retained_grant();let result=cx.with_native_receiving(|native|store.step_derived_report_replay(replay.as_mut().unwrap(),grant,native,&mut||false));let p=replay.as_mut().unwrap().take_preparation_receipt();if let Some(issued)=cx.receiving_issued_grant(){cx.consume_receiving_retained(issued,p)?;}else{cx.consume_retained(p)?;}cx.consume_fuel(p.copied_items as u64);Ok(matches!(result.unwrap(),store::os_store::replay::ReplayStep::Finished(_)))});if ready{break}assert!(index<262143,"original finalization Report stalled");}
 let(finished,head)=store.finish_derived_report_replay(&mut replay).unwrap();drop(head);assert!(replay.is_none());finished
}
fn exercise_finalization(mode:&str){
 type Publisher=store::os_store::original_replay_publication::OriginalReplayPublication<State,Mutation>;let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();for cut in law["cancelCuts"].as_array().unwrap().iter().map(|v|Some(v.as_u64().unwrap()as usize)).chain([None]){let mut caller=caller();let mut decoder=OriginalJobDecodeOwner::empty();let mut store=native_document_store(&mut caller,&mut decoder);let mut result=Some(prepare_report(&mut store,&mut caller,&mut decoder));let state=result.as_ref().unwrap().state.as_ref().unwrap().as_ref()as*const State;let mut request=Some(match mode{"overwrite"=>store::HistoryFinalization::Overwrite,"scope"=>store::HistoryFinalization::Scope{alternative_id:store.trunk_alternative_id()},"alternative"=>store::HistoryFinalization::Alternative{name:String::from("Original replay alternative λ")},_=>unreachable!()});let mut publisher=None;assert!(result.as_ref().unwrap().original_decode.is_some());let mut foreign_decoder=OriginalJobDecodeOwner::empty();turn(&mut caller,&mut foreign_decoder,TURN,|cx|{assert!(Publisher::admit(&store,&mut result,&mut request,cx,&mut publisher).is_err());Ok(())});assert!(foreign_decoder.terminal_is_empty());assert!(publisher.is_none()&&request.is_some());assert_eq!(result.as_ref().unwrap().state.as_ref().unwrap().as_ref()as*const State,state);let d=Publisher::capture_demands();assert!(d.copy_bytes<=32768&&d.capacity_bytes<=16<<20,"publisher fixed frame exceeds actual mounted policy: {d:?}");let g=RetainedCloneGrant{maximum_copy_bytes:32768,maximum_capacity_bytes:16<<20,..TURN};
 for axis in law["deniedAxes"].as_array().unwrap(){let mut denied=g;let limit=match axis.as_str().unwrap(){"items"=>&mut denied.maximum_items,"copy"=>&mut denied.maximum_copy_bytes,"capacity"=>&mut denied.maximum_capacity_bytes,"release"=>continue,_=>&mut denied.maximum_depth};*limit=match axis.as_str().unwrap(){"copy"=>d.copy_bytes-1,"capacity"=>d.capacity_bytes-1,_=>0};turn(&mut caller,&mut decoder,denied,|cx|{assert!(!Publisher::admit(&store,&mut result,&mut request,cx,&mut publisher)?);Ok(())});assert!(publisher.is_none()&&request.is_some());assert_eq!(result.as_ref().unwrap().state.as_ref().unwrap().as_ref()as*const State,state);}
 turn(&mut caller,&mut decoder,g,|cx|{assert!(Publisher::admit(&store,&mut result,&mut request,cx,&mut publisher)?);Ok(())});assert!(result.is_none()&&request.is_none());for index in 0..262144{if cut==Some(index){caller.cancel().cancel_now();break}let ready=turn(&mut caller,&mut decoder,g,|cx|publisher.as_mut().unwrap().advance(&mut store,cx));assert_eq!(store.snapshot().unwrap().zoom,law["preparedVisible"].as_f64().unwrap());assert!(store.parts_ref().log.envelope.transitions.is_empty());if ready{break}assert!(index<262143,"captured original publication preparation stalled");}if cut.is_none(){assert!(publisher.as_ref().unwrap().prepared());let before=store.generation();turn(&mut caller,&mut decoder,g,|cx|{assert!(publisher.as_mut().unwrap().publish(&mut store,cx)?);Ok(())});assert_eq!(store.generation(),before+1);assert_eq!(store.snapshot().unwrap().zoom,law["publishedVisible"].as_f64().unwrap());assert_eq!(store.parts_ref().log.envelope.transitions.len(),if mode=="alternative"{3}else{1});assert_eq!(store.parts_ref().wire.original_outbox.len(),1);let mut receipt=None;turn(&mut caller,&mut decoder,g,|cx|{assert!(publisher.as_mut().unwrap().take_receipt(cx,&mut receipt)?);Ok(())});let receipt=receipt.unwrap();assert_eq!(receipt.generation_before,before);assert_eq!(receipt.generation_after,before+1);assert_eq!(receipt.revision,store.content_revision());assert!(receipt.applies_to_head);turn(&mut caller,&mut decoder,g,|cx|{assert!(publisher.as_mut().unwrap().acknowledge(cx)?);Ok(())});}
 for index in 0..262144{let ready=turn(&mut caller,&mut decoder,g,|cx|cx.with_original_retirement(|cx|publisher.as_mut().unwrap().close_step(&mut store,cx)));if ready{break}assert!(index<262143,"captured original publication close stalled");}assert!(publisher.as_ref().unwrap().terminal_is_empty());turn(&mut caller,&mut decoder,g,|cx|cx.with_original_retirement(|cx|{let d=Publisher::boxed_release_demands();close_original_retained_step(cx,d,|_|{publisher=None;Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,released_bytes:d.release_bytes,..Default::default()}))})?;Ok(())}));
 for index in 0..1048576{if store.close_owned_store_terminal_is_empty(){break}turn(&mut caller,&mut decoder,g,|cx|cx.with_original_retirement(|cx|{let d=store.close_owned_demands(4096)?;close_original_retained_step(cx,d,|grant|store.close_owned_store_step(grant))?;Ok(())}));assert!(index<1048575);}release_native_store_box(store,&mut caller,&mut decoder);while !decoder.terminal_is_empty(){caller.turn(g,|cx|cx.with_original_retirement(|cx|{let d=decoder.retirement_demands(4096)?;close_original_retained_step(cx,d,|grant|decoder.close_step(grant))?;Ok(())})).unwrap();}caller.retire(g);
 }
}

#[test]fn original_completed_replay_capture_prepares_privately_and_closes_cancelled_sources(){for mode in ["overwrite","scope","alternative"]{exercise_finalization(mode);}}

#[test]fn original_time_travel_store_drives_same_completed_report_recipient_through_ack_and_close(){
 use semio_framework_plugin_time_travel::{TimeTravelStoreState,TimeTravelCommit,TimeTravelOwners};
 let mut caller=caller();let mut decoder=OriginalJobDecodeOwner::empty();let mut store=native_document_store(&mut caller,&mut decoder);let mut report=Some(prepare_report(&mut store,&mut caller,&mut decoder));let mut request=Some(store::HistoryFinalization::Overwrite);let mut state=TimeTravelStoreState::<State,Mutation>::new(|_|unreachable!("fixture label is not requested by native finalize"));let g=RetainedCloneGrant{maximum_copy_bytes:32768,maximum_capacity_bytes:16<<20,..TURN};turn(&mut caller,&mut decoder,g,|cx|{assert!(state.commit_report(&store,&mut report,&mut request,cx)?);Ok(())});assert!(report.is_none()&&request.is_none());let mut foreign=OriginalJobDecodeOwner::empty();turn(&mut caller,&mut foreign,g,|cx|{assert!(state.step_commit(&mut store,cx).is_err());Ok(())});assert!(foreign.terminal_is_empty());assert!(state.finalizing());let before=store.generation();let mut completed=None;for index in 0..262144{let outcome=turn(&mut caller,&mut decoder,g,|cx|state.step_commit(&mut store,cx).map_err(Into::into));match outcome{TimeTravelCommit::Pending=>{},TimeTravelCommit::Finalized{receipt}=>{completed=Some(receipt);break},other=>panic!("original typed finalization returned {other:?}")}assert!(index<262143,"original typed finalization stalled");}let receipt=completed.unwrap();assert_eq!(receipt.generation_before,before);assert_eq!(receipt.generation_after,store.generation());assert_eq!(store.snapshot().unwrap().zoom,3.75);assert!(!state.finalizing());assert!(TimeTravelOwners::terminal_is_empty(&state));drop(state);for index in 0..1048576{if store.close_owned_store_terminal_is_empty(){break}turn(&mut caller,&mut decoder,g,|cx|cx.with_original_retirement(|cx|{let d=store.close_owned_demands(4096)?;close_original_retained_step(cx,d,|grant|store.close_owned_store_step(grant))?;Ok(())}));assert!(index<1048575);}release_native_store_box(store,&mut caller,&mut decoder);while !decoder.terminal_is_empty(){caller.turn(g,|cx|cx.with_original_retirement(|cx|{let d=decoder.retirement_demands(4096)?;close_original_retained_step(cx,d,|grant|decoder.close_step(grant))?;Ok(())})).unwrap();}caller.retire(g);
}
